/**
 ******************************************************************************
 * @file    crossover.c
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant.
 * @brief   Speaker crossover at 1600 Hz: LR4 high-pass to the tweeter
 *          (left), LR4 low-pass plus a 10 Hz high-pass to the subwoofer
 *          (right).
 *
 * Pure: no RTOS, no HAL. Run by TomTask on every 4 ms half; crossover.h
 * explains what a crossover does and why two Butterworth biquads in a row
 * make a Linkwitz-Riley filter whose two sides add up flat.
 *
 * Main steps:
 *   Crossover_Init                  work out the numbers with the "Audio EQ
 *                                   Cookbook" formulas of Robert
 *                                   Bristow-Johnson (the "RBJ cookbook"),
 *                                   clear the memories
 *   Crossover_ProcessInterleaved    per frame: left through the tweeter
 *                                   filter, right through the subwoofer
 *                                   filter; skip a silent, rung-down half
 * Tests: Tests/OutputChain/test_crossover.c.
 ******************************************************************************
 */
#include "crossover.h"

#include <math.h>
#include <stddef.h>

#define CROSSOVER_PI    3.14159265f

/* ------------------------------------------------------------------------ */
/* Filter numbers                                                            */
/* ------------------------------------------------------------------------ */

/*
 * The cookbook's design method (the bilinear transform): a filter at f_c
 * for a sample rate f_s starts from k = tan(pi f_c / f_s), the "pre-warped"
 * corner, so that the digital filter's corner lands exactly on f_c.
 */
static float prewarped_corner(float corner_hz, float sample_rate_hz)
{
    return tanf(CROSSOVER_PI * corner_hz / sample_rate_hz);
}

/* The cookbook scales every number by norm = 1 / (1 + k/Q + k^2). */
static float butterworth_norm(float k)
{
    return 1.0f / (1.0f + (k / CROSSOVER_BUTTERWORTH_Q) + (k * k));
}

/*
 * The feedback numbers (a1, a2) of a 2nd-order filter with corner k and
 * quality Q. A low-pass and a high-pass at the same corner share them; only
 * b0, b1 and b2 differ. With Q = 1/sqrt(2) the section is a Butterworth
 * one: as flat as possible in its pass band, -3 dB at the corner.
 *     a1 = 2 (k^2 - 1) norm
 *     a2 = (1 - k/Q + k^2) norm
 */
static void set_butterworth_feedback(CrossoverBiquad *biquad, float k, float norm)
{
    biquad->a1 = 2.0f * ((k * k) - 1.0f) * norm;
    biquad->a2 = (1.0f - (k / CROSSOVER_BUTTERWORTH_Q) + (k * k)) * norm;
    biquad->z1 = 0.0f;
    biquad->z2 = 0.0f;
}

/* Low-pass: b0 = k^2 norm, b1 = 2 b0, b2 = b0 (full level at 0 Hz). */
static void make_butterworth_low_pass(CrossoverBiquad *biquad, float corner_hz, float sample_rate_hz)
{
    const float k = prewarped_corner(corner_hz, sample_rate_hz);
    const float norm = butterworth_norm(k);

    biquad->b0 = k * k * norm;
    biquad->b1 = 2.0f * biquad->b0;
    biquad->b2 = biquad->b0;
    set_butterworth_feedback(biquad, k, norm);
}

/* High-pass: b0 = norm, b1 = -2 b0, b2 = b0 (full level at half the sample rate). */
static void make_butterworth_high_pass(CrossoverBiquad *biquad, float corner_hz, float sample_rate_hz)
{
    const float k = prewarped_corner(corner_hz, sample_rate_hz);
    const float norm = butterworth_norm(k);

    biquad->b0 = norm;
    biquad->b1 = -2.0f * biquad->b0;
    biquad->b2 = biquad->b0;
    set_butterworth_feedback(biquad, k, norm);
}

/*
 * 1st-order high-pass, same method: b0 = 1 / (1 + k), a1 = (1 - k) / (1 + k).
 * At 10 Hz out of 48 kHz: b0 = 0.99935, a1 = 0.99869.
 */
static void make_first_order_high_pass(CrossoverFirstOrderHighPass *filter, float corner_hz,
                                       float sample_rate_hz)
{
    const float k = prewarped_corner(corner_hz, sample_rate_hz);

    filter->b0 = 1.0f / (1.0f + k);
    filter->a1 = (1.0f - k) / (1.0f + k);
    filter->x_prev = 0.0f;
    filter->y_prev = 0.0f;
}

void Crossover_Init(Crossover *crossover, float sample_rate_hz)
{
    if (crossover == NULL)
    {
        return;
    }

    /* Two identical sections per side: Butterworth squared = Linkwitz-Riley (LR4). */
    for (uint32_t section = 0U; section < CROSSOVER_SECTIONS_PER_SIDE; section++)
    {
        make_butterworth_high_pass(&crossover->tweeter[section], CROSSOVER_POINT_HZ, sample_rate_hz);
        make_butterworth_low_pass(&crossover->sub[section], CROSSOVER_POINT_HZ, sample_rate_hz);
    }
    make_first_order_high_pass(&crossover->sub_high_pass, CROSSOVER_SUB_HP_HZ, sample_rate_hz);
}

void Crossover_Reset(Crossover *crossover)
{
    if (crossover == NULL)
    {
        return;
    }

    for (uint32_t section = 0U; section < CROSSOVER_SECTIONS_PER_SIDE; section++)
    {
        crossover->tweeter[section].z1 = 0.0f;
        crossover->tweeter[section].z2 = 0.0f;
        crossover->sub[section].z1 = 0.0f;
        crossover->sub[section].z2 = 0.0f;
    }
    crossover->sub_high_pass.x_prev = 0.0f;
    crossover->sub_high_pass.y_prev = 0.0f;
}

/* ------------------------------------------------------------------------ */
/* Filtering                                                                 */
/* ------------------------------------------------------------------------ */

/*
 * One sample through one biquad (transposed direct form II). It computes
 *     y = b0 x + b1 x[n-1] + b2 x[n-2] - a1 y[n-1] - a2 y[n-2]
 * but keeps the old samples pre-added in two memories, z1 and z2, which
 * needs fewer operations and stays accurate in float.
 */
static float biquad_step(CrossoverBiquad *biquad, float x)
{
    const float y = (biquad->b0 * x) + biquad->z1;

    biquad->z1 = (biquad->b1 * x) - (biquad->a1 * y) + biquad->z2;
    biquad->z2 = (biquad->b2 * x) - (biquad->a2 * y);
    return y;
}

/* y = b0 (x - x_prev) + a1 y_prev: follows changes, lets a constant die away. */
static float first_order_high_pass_step(CrossoverFirstOrderHighPass *filter, float x)
{
    const float y = (filter->b0 * (x - filter->x_prev)) + (filter->a1 * filter->y_prev);

    filter->x_prev = x;
    filter->y_prev = y;
    return y;
}

/* Left: the LR4 high-pass (two Butterworth high-pass biquads in a row). */
static float tweeter_filter(Crossover *crossover, float x)
{
    const float first = biquad_step(&crossover->tweeter[0], x);
    return biquad_step(&crossover->tweeter[1], first);
}

/* Right: the LR4 low-pass, then the 10 Hz high-pass. */
static float sub_filter(Crossover *crossover, float x)
{
    const float first = biquad_step(&crossover->sub[0], x);
    const float second = biquad_step(&crossover->sub[1], first);
    return first_order_high_pass_step(&crossover->sub_high_pass, second);
}

/* To the nearest whole sample (halves away from zero), clipped to int16:
 * a sharp step makes the filters overshoot past full scale, and a value
 * that wrapped around would flip sign (a loud click). */
static int16_t round_and_clip(float value)
{
    if (value > 32767.0f)
    {
        return INT16_MAX;
    }
    if (value < -32768.0f)
    {
        return INT16_MIN;
    }
    if (value >= 0.0f)
    {
        return (int16_t)(value + 0.5f);
    }
    return (int16_t)(value - 0.5f);
}

static bool memory_is_quiet(float value)
{
    return fabsf(value) < CROSSOVER_RUNG_DOWN_LEVEL;
}

/* Every filter memory below CROSSOVER_RUNG_DOWN_LEVEL: their output now
 * rounds to 0 for good, so on silence the filters have nothing to add. */
static bool filters_have_rung_down(const Crossover *crossover)
{
    for (uint32_t section = 0U; section < CROSSOVER_SECTIONS_PER_SIDE; section++)
    {
        if (!memory_is_quiet(crossover->tweeter[section].z1) ||
            !memory_is_quiet(crossover->tweeter[section].z2) ||
            !memory_is_quiet(crossover->sub[section].z1) ||
            !memory_is_quiet(crossover->sub[section].z2))
        {
            return false;
        }
    }
    return memory_is_quiet(crossover->sub_high_pass.x_prev) &&
           memory_is_quiet(crossover->sub_high_pass.y_prev);
}

static bool block_is_silent(const int16_t *lr, uint32_t frames)
{
    for (uint32_t i = 0U; i < 2U * frames; i++)
    {
        if (lr[i] != 0)
        {
            return false;
        }
    }
    return true;
}

/*
 * The silence bypass: TomTask calls this every 4 ms for ever, also while
 * nothing plays (the DMA never stops). On a silent half whose filters have
 * rung down, filtering would only produce zeros again, so it is skipped,
 * and the caller is told (true) so it can skip its speaker trim as well.
 * That keeps TomTask near 1 % of the CPU while effect files are being made.
 */
bool Crossover_ProcessInterleaved(Crossover *crossover, int16_t *lr, uint32_t frames)
{
    if ((crossover == NULL) || (lr == NULL) || (frames == 0U))
    {
        return false;
    }

    if (filters_have_rung_down(crossover) && block_is_silent(lr, frames))
    {
        Crossover_Reset(crossover);     /* exact zeros: no tiny leftovers ever build up */
        return true;
    }

    for (uint32_t frame = 0U; frame < frames; frame++)
    {
        const uint32_t left = 2U * frame;       /* interleaved: [L, R, L, R, ...] */
        const uint32_t right = left + 1U;

        lr[left] = round_and_clip(tweeter_filter(crossover, (float)lr[left]));
        lr[right] = round_and_clip(sub_filter(crossover, (float)lr[right]));
    }
    return false;
}
